"sdp.overview.serviceCatalog.fieldAndFormRules.content" : "<p>The types of fields required in a request form may vary with different request templates. While the type of fields required can be dragged and dropped in the canvas, the rules for those fields and behavior of that particular request form can be set in the Field and Form Rules section available in the respective request templates. You can create new rules and configure them to be applied when the request form loads or when a particular field in a form changes or while submitting the request form. You can also copy rules of one template to another and add or remove fields and rules. Field and form rules have variety of options like enabling and disabling fields, show or hide fields, mandate certain fields, execute actions based on scripts etc.,</p>",
