"sdp.overview.assetMgmt.purchaseOrder.content" : "<p>The Purchase Order (PO) module helps you streamline the procurement of IT assets and components. You can create and maintain a product catalog with all products in your organization, and other details like associated vendor, cost of the asset, time of purchase, payment information, etc. You can also maintain a list of all your vendors with their price quotes to make informed decisions while purchasing the assets. With all purchase orders documented, you can analyze the cost and discounts of previous purchases to get better deals in the future. The PO module supports purchase request (PR) process too, purchase request is a process to record and document the organization\u00ef\u00bf\u00bd??s approval of a purchase transaction prior to creating the PO. The purchase module supports a multi-level approval process, that helps you to ensure that all POs are sent to the vendor only after proper approvals. You can easily analyze your purchase patterns and perform vendor-based purchase analysis by generating reports.</p>",
