"sdp.overview.assetMgmt.sftLicensing.content" : "<p>Tracking and managing software licenses can be a nightmare to most IT departments. Improper management of software licenses can lead to license violations as per vendor norms. ServiceDesk Plus helps you scan all your workstations to discover and import all information about the installed software automatically. You can classify the software as managed, shareware, freeware, prohibited, and categorize them for efficient tracking and management. You can also purchase, distribute, track, and manage software licenses to attain complete software license compliance.</p>",
