"sdp.overview.integrations.zohoReports.content" : "<p>The Advanced Analytics module auto-analyzes your ServiceDesk Plus data to offer business intelligence reporting, helping you make better decisions everyday.</p><ol><li>In depth analysis of your ServiceDesk Plus data with over a 100+ reports and dashboards, built on 80+ KPIs.</li><li>Charts from various {0} modules can be combined on to a single dashboard and scheduled for distribution.</li> <li>Easily drill down to a specific time period or apply filters based on key metrics right from within the dashboards.</li> <li>Drag and drop report builder lets you develop custom metrics without having to write complex SQL queries.</li> <li>Share and publish dashboards across the organization or to specific users.</li><li>Integrate third party data from sources like SQL and No SQL databases, XML, JSON, XML, HTML, CSV, XLS, APIs and more.</li></ol>",
