"sdp.overview.assetMgmt.assetLifecycle.content" : "<p>Asset management module of ServiceDesk Plus helps you track the life cycle of assets from procurement to disposal of assets. The usual life cycle of an asset has different stages such as procurement, deployment, maintenance, warranty, retirement and disposal. Tracking the asset life cycle helps you stay on top of any changes to the assets. Maintaining an history of all hardware and software installations on your assets helps you check and reuse software licenses after asset disposal. You can also configure depreciation details for a particular asset to calculate its depreciation value over a period of time.</p>",
