"sdp.overview.requestMgmt.technicianPortal.content" : "<p>Technicians can log into the web-based portal to manage the requests assigned to them. The request list view presents view of all requests. The list view can be customized according to individual technician needs. Clicking on a request opens the Request Details view which shows the full details of the request. The technician can add notes to record action taken and add time work logs to capture the effort. Related requests can be linked and common operations like adding notes, work logs, resolution to linked requests can be done together. The technician can also manage tasks, or sub-activities of a request. Multiple tasks can be created for a request and if needed, each task can be assigned to a different technician. Dependency among tasks can be configured. After providing the resolution, the technician can close the request. You can configure request and task closing rules marking certain fields to be mandatorily filled in before closing the request. Throughout the request life cycle, the request passes through different statuses. For each status, you can configure the SLA timer to run or you can put the timer on hold while awaiting response from the end user on a query.</p>",
