"sdp.overview.assetMgmt.maintenanceContracts.content" : "<p>A lot of your IT assets might be maintained and serviced by various third party vendors under annual maintenance contracts. Multiple vendors, involved with varied renewal schedules, can complicate the process of tracking the contracts. There are chances of missing out the contract renewal leading to unnecessary repair expenses. You can easily track the maintenance contracts of assets, software, and services using the contracts section. You can get a holistic view of each contract, capturing details such as vendor name and address, support terms, active period, assets covered under contracts, and more. You can also set notification alerts for contract expiration and choose to get notified before the contracts expire. You can also filter out assets without contract to check if the contract needs to be extended for those assets.</p>",
