"sdp.overview.serviceCatalog.workflow.content" : "<p>When users logs in, Service templates allowed for the user alone will be shown and user can select and fill relevant info for the template. Tasks included for the template will be added for the Service Request. Notification seeking approval will be automatically sent to approving authority. The SLA timer for the request will be stopped till the request approval action is completed. Once the request is approved, tasks will be automatically triggered so that task technician can start fulfilling the request. Email notifications can be configured to request technician, task technician, end user so as to keep them informed on the request status. Different tasks can be assigned to different technician. Dependent tasks will get triggered based on Task dependency marking. Request can be closed after completing all the associated tasks.</p>",
