"sdp.overview.changeMgmt.changeflow.content" : "<p>You can manage the complete life cycle of IT changes from start to finish. When a change request is raised, an initial analysis is done to determine its necessity. Users are assigned different roles like, change owner, change manager, change analyzer, implementer, line manager, change reviewer, etc. For the change analysis, you can create impact, roll out, and back out plans and implementation checklists. The CAB members evaluate these inputs and provide their recommendation for the change. Based on the CAB members' recommendations and comments, the change manager will approve the change for implementation. A Post Implementation Review (PIR) is carried out to take stock of the learnings. Finally, the change is closed with a change closure code.</p>",
