"sdp.overview.requestMgmt.serviceLvlAgmt.content" : "<p>Service Level Agreements (SLAs) can be defined for the services provided by the service desk team to their end users. These SLAs ensure that issues are resolved within agreed upon time. You can create site-specific SLAs to ensure better service across all your operational sites. You can configure response and resolution SLAs and define escalation paths. You can configure SLAs based on parameters like priority, impact, urgency, department, requester, service category, VIP user, etc. You can also configure actions from move to group / technician and set different priorities, levels when escalation levels are matched.</p>",
