"cmdb.migration.intro.para5" : "Now that the migration takes care of creating the parent CI type's attributes as Asset Additional fields (under the appropriate Product Type), please execute the following steps based on your environment for moving Child CI Type and/or its Attributes as Asset Additional Fields.",
