"standard.hours" : "Standard Hours",
"cmdb.migration.intro.para4" : "As you upgrade to version {0}, we will assist you in migrating CI Attributes to Asset Additional Fields. This migration will automatically create CI Attributes in the parent CI Type as Additional fields under the Asset's Product Type. Therefor, a CI Sync Rule is automatically created, associating the CI Type with the Product Type and mapping CI Attributes to Asset fields.",
"cmdb.migration.intro.para3" : "Therefore, not all assets created in the Assets module will be categorized as CIs under CMDB, and vice versa. Additionally, asset additional fields will now only be displayed under assets, and attributes defined under CMDB will only be displayed under CIs.",
"cmdb.migration.intro.para2" : "However, from version {0}, not all assets, users, and services  will be considered as CIs; only those critical to your organization and requiring more attention to provide successful IT service will be considered as CIs.",
