"cmdb.migration.intro.para1" : "In versions before {0}, all assets created in the Assets module are considered Configuration Items (CI) under CMDB and vice versa. This applies to all cases of asset addition, such as manual entry, scanning, or CSV import. Asset Additional fields and CI Attributes are displayed in both Assets and CIs.",
