"sdp.overview.integrations.opm.content" : "<p>ManageEngine OpManager (OPM) is a server and network monitoring software used by enterprises to manage their data centers and IT infrastructure efficiently. By integrating OpManager with ServiceDesk Plus you can detect faults and performance issues in your network and get instant notifications. You can also enable automatic creation of tickets in the IT help desk in case of network failures. All workstation, and server details along with the relationship configurations can be viewed directly from the OpManager application when necessary. From the OPM device details page, you can invoke the workstation or server details scanned, and view relationships configured in ServiceDesk Plus for a particular device.</p>",
