"sdp.overview.changeMgmt.chngWorkflow.content" : "<p>Change workflows let you manage the life cycle of changes. Every organization has different types of changes and different workflows. A server hardware change could take a different workflow than an MSSQL upgrade. Likewise, a change to firewall settings needs to be dealt differently than a webpage change. Standard (pre-approved) changes, normal, and emergency changes can each have their unique workflows. You can define different stages of a change and within each stage, configure the different statuses a change can go through. Change workflows define the movement of the change through multiple stages or statuses and e-mail notifications can be triggered and sent to change members at every step of the workflow.</p>",
