"sdp.overview.assetMgmt.assetScan.content" : "<p>In order to manage your IT assets effectively, first you need to know all about the hardware and software assets present in the organization. With ServiceDesk Plus, you can scan all your IT hardware assets by creating an agent and deploying it in all windows workstations through Active Directory group policy. The scan fetches you the complete hardware and software information of the workstations. You can also scan non-windows workstations like Linux, MAC, Solaris, and AIX operating systems. ServiceDesk Plus also helps you scan the virtual hosts and capture the VM host ( Virtual Machine) relationships.</p>",
