"sdp.overview.serviceCatalog.templatesFormCustom.content" : "<p>For each service that you offer, you can create your own custom template with default and custom fields. Fields can be marked as mandatory and the form layout can be reordered using a drag and drop functionality. You can provide a personalized experience for end users in the self-service portal by presenting only those services that the end users are entitled to or those that are relevant to their role. For each template, you can also assign SLAs, configure workflows, define multi-stage approval processes, and set task dependencies.</p>",
